/* Hidden attribute override guarantee */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1e1b2e;
  --card-bg: #2d2645;
  --primary: #ffb703;
  --primary-hover: #ffa200;
  --accent: #fb8500;
  --text-main: #f8f9fa;
  --text-muted: #c4b5fd;
  --card-border: #443b68;
  --danger: #ef476f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-color);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  color: var(--text-main);
  padding: 20px;
}

.auction-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 12px;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 440px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  text-align: center;
}

.auction-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.auction-title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text-main);
}

.pixel-art {
  width: 96px;
  height: 96px;
  background: #171322;
  border: 3px solid var(--card-border);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.6);
}

/* 6x6 pure CSS pixel art icon */
.pixel-grid {
  width: 12px;
  height: 12px;
  background: transparent;
  box-shadow:
    12px 0 0 0 var(--primary),
    24px 0 0 0 var(--primary),
    36px 0 0 0 var(--primary),
    0 12px 0 0 var(--primary),
    12px 12px 0 0 #fff,
    24px 12px 0 0 var(--accent),
    36px 12px 0 0 var(--accent),
    48px 12px 0 0 var(--primary),
    0 24px 0 0 var(--primary),
    12px 24px 0 0 var(--accent),
    24px 24px 0 0 #fff,
    36px 24px 0 0 var(--accent),
    48px 24px 0 0 var(--primary),
    0 36px 0 0 var(--primary),
    12px 36px 0 0 var(--accent),
    24px 36px 0 0 var(--accent),
    36px 36px 0 0 var(--accent),
    48px 36px 0 0 var(--primary),
    12px 48px 0 0 var(--primary),
    24px 48px 0 0 var(--primary),
    36px 48px 0 0 var(--primary);
  transform: translate(-24px, -24px);
}

.item-name {
  font-size: 1rem;
  color: var(--text-muted);
}

.auction-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.stat-box {
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--card-border);
  border-radius: 8px;
  padding: 14px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
}

.stat-value {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--primary);
}

.stat-value.warning {
  color: var(--danger);
}

.auction-controls {
  display: flex;
  gap: 16px;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 14px 16px;
  border-radius: 8px;
  border: 2px solid transparent;
  background-color: var(--primary);
  color: #171322;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.btn:hover:not(:disabled) {
  background-color: var(--primary-hover);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255, 183, 3, 0.3);
}

.btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 3px;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
  box-shadow: none;
}

.btn:disabled {
  background-color: #4a4364;
  color: #8c82a8;
  cursor: not-allowed;
  opacity: 0.6;
  transform: none;
  box-shadow: none;
}

.status-message {
  padding: 14px;
  border-radius: 8px;
  background: rgba(255, 183, 3, 0.15);
  border: 1px solid var(--primary);
  color: var(--primary);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

@media (max-width: 360px) {
  .auction-card {
    padding: 18px 14px;
  }

  .stat-value {
    font-size: 1.5rem;
  }

  .btn {
    font-size: 1rem;
    padding: 12px 8px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const STARTING_PRICE = 10;
  const INITIAL_COUNTDOWN = 45;
  const EXTENSION_SECONDS = 10;

  let currentPrice = STARTING_PRICE;
  let remainingTime = INITIAL_COUNTDOWN;
  let timerId = null;
  let isAuctionEnded = false;

  const priceDisplay = document.getElementById('current-price');
  const timerDisplay = document.getElementById('timer-display');
  const statusMessage = document.getElementById('auction-status');
  const bid1Btn = document.getElementById('bid-1-btn');
  const bid5Btn = document.getElementById('bid-5-btn');

  function updateDisplays() {
    priceDisplay.textContent = currentPrice;
    timerDisplay.textContent = `${remainingTime}s`;

    if (remainingTime <= EXTENSION_SECONDS) {
      timerDisplay.classList.add('warning');
    } else {
      timerDisplay.classList.remove('warning');
    }
  }

  function endAuction() {
    isAuctionEnded = true;
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }

    timerDisplay.textContent = '0s';
    timerDisplay.classList.remove('warning');

    bid1Btn.disabled = true;
    bid5Btn.disabled = true;

    statusMessage.textContent = `Sold for ${currentPrice}`;
    statusMessage.removeAttribute('hidden');
  }

  function startTimer() {
    timerId = setInterval(() => {
      remainingTime -= 1;
      if (remainingTime <= 0) {
        endAuction();
      } else {
        updateDisplays();
      }
    }, 1000);
  }

  function placeBid(increment) {
    if (isAuctionEnded) return;

    currentPrice += increment;

    // If bid occurs in the last 10 seconds, countdown restarts at 10 seconds
    if (remainingTime <= EXTENSION_SECONDS) {
      remainingTime = EXTENSION_SECONDS;
    }

    updateDisplays();
  }

  bid1Btn.addEventListener('click', () => placeBid(1));
  bid5Btn.addEventListener('click', () => placeBid(5));

  updateDisplays();
  startTimer();
});
